    internal InnerMediaPipelineKinesisVideoStreamPoolStreamConfigurationFactory StreamConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaPipelineKinesisVideoStreamPool Create()
    {
        var mediaPipelineKinesisVideoStreamPoolResult = CreateMediaPipelineKinesisVideoStreamPool();
        factoryAction?.Invoke(mediaPipelineKinesisVideoStreamPoolResult);

        return mediaPipelineKinesisVideoStreamPoolResult;
    }

    private Humidifier.Chime.MediaPipelineKinesisVideoStreamPool CreateMediaPipelineKinesisVideoStreamPool()
    {
        var mediaPipelineKinesisVideoStreamPoolResult = new Humidifier.Chime.MediaPipelineKinesisVideoStreamPool
        {
            GivenName = InputResourceName,
        };

        return mediaPipelineKinesisVideoStreamPoolResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaPipelineKinesisVideoStreamPool result)
    {
        base.CreateChildren(result);

        result.Tags = TagsFactories.Any() ? TagsFactories.Select(x => x.Build()).ToList() : null;
        result.StreamConfiguration ??= StreamConfigurationFactory?.Build();
    }

